def get_legal_reference_data(question_obj):
    if not question_obj:
        return None
        
    subject = question_obj.get('subject', '')
    qid = str(question_obj.get('id', ''))
    law_ref = str(question_obj.get('law_ref', '')).strip()
    topic = str(question_obj.get('topic', '')).strip()
    explanation = str(question_obj.get('explanation', '')).strip()
    question_text = str(question_obj.get('question', '')).strip()
    category = str(question_obj.get('category', '')).strip()
    
    is_computer = (subject == 'computer' or qid.startswith('COM'))
    if is_computer:
        return None
        
    # 1. Check for specific Section Number in พ.ร.บ.องค์กรอัยการและพนักงานอัยการ พ.ศ. 2553
    sec_match = re.search(r'(?:มาตรา|ม\.)\s*(?:ที่\s*)?(\d{1,2})\b', f"{law_ref} {topic} {question_text} {explanation}")
    if sec_match:
        sec_num = int(sec_match.group(1))
        if sec_num in (28, 29):
            return LEGAL_DB['oag_sec_28_29']
        key = f'oag_sec_{sec_num}'
        if key in LEGAL_DB:
            return LEGAL_DB[key]
            
    # 2. Match by keywords
    combined_query = f"{law_ref} {topic} {question_text} {explanation}"
    best_match = None
    max_matches = 0
    for key, data in LEGAL_DB.items():
        if key == 'computer_crime_act':
            continue
        matches = sum(1 for kw in data['keywords'] if kw.lower() in combined_query.lower())
        if matches > max_matches:
            max_matches = matches
            best_match = data
            
    if best_match:
        return best_match
        
    return LEGAL_DB['oag_sec_1']

def render_legal_reference_expander(question_obj, expanded=False):
    legal_data = get_legal_reference_data(question_obj)
    if not legal_data:
        return
        
